-- A2.2: reader-first descriptions for the 15 published foundation technologies.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('houseplatform:m2-foundations-a22-editorial'));

CREATE TEMP TABLE a22_descriptions (code text PRIMARY KEY, description text NOT NULL) ON COMMIT DROP;
INSERT INTO a22_descriptions VALUES
('FND_BASEMENT_WALL_MONOLITHIC',
 'Монолитная стена подвала удерживает грунт, ограждает подземное помещение и передает нагрузки на основание через фундаментную часть. Сначала готовят основание и опалубку, затем размещают арматуру и закладные элементы, укладывают бетон и защищают стену от воды. Особое внимание уделяют швам, проходкам коммуникаций и сопряжению стены с плитой или лентой.'),
('FND_COLUMN_CONCRETE_RC',
 'Столбчатый фундамент состоит из отдельных бетонных или железобетонных опор под точками передачи нагрузки. Для каждой опоры подготавливают основание, устраивают форму и, если предусмотрено, армирование, затем бетонируют и соединяют с несущей частью здания. Нужно проверить положение опор и способ передачи нагрузки между ними; такая схема не равнозначна непрерывной ленте.'),
('FND_PILE_BORED_RC',
 'Буронабивная свая формируется в скважине: сначала бурят и контролируют ее состояние, затем устанавливают арматурный каркас и укладывают бетон. Сваи передают нагрузку через тело и нижнюю часть в грунт, а их головы связываются с конструкцией выше. Вода и устойчивость стенок скважины влияют на способ устройства; это необходимо проверить до бетонирования.'),
('FND_PILE_DRIVEN_RC',
 'Забивная железобетонная свая изготавливается заранее и погружается в грунт строительной техникой. После приемки изделий размечают точки установки, погружают сваи с контролем положения и состояния, затем подготавливают головы для соединения с ростверком. Поврежденное изделие нельзя считать пригодным только по факту погружения.'),
('FND_PILE_GRILLAGE',
 'Ростверк объединяет головы свай и распределяет нагрузку здания между ними. После приемки свай подготавливают их головы и сопряжения, устраивают опалубку и армирование ростверка, укладывают бетон и принимают соединения. Тип свай и способ их связи с ростверком должны быть совместимы; это отдельный узел системы.'),
('FND_PILE_SCREW',
 'Стальная винтовая свая имеет ствол и лопасть, с помощью которых она погружается в грунт. После проверки изделий и разметки выполняют погружение, контролируют положение, устраивают оголовки и соединение с обвязкой, восстанавливают защиту поврежденных участков. Состояние стали и защита от коррозии важны не меньше самого монтажа.'),
('FND_SLAB_MONOLITHIC_RC',
 'Монолитная фундаментная плита распределяет нагрузку здания по площади подготовленного основания. Работы идут от подготовки и приемки основания к опалубке, армированию и бетонированию; затем выполняют уход за бетоном и предусмотренную защиту. Перед заливкой особенно важно проверить проходки, защитный слой, положение арматуры и готовность основания.'),
('FND_SLAB_RIBBED_RC',
 'Ребристая плита состоит из плитной части и усиливающих ребер, которые работают совместно. Подготавливают основание и форму ребер, размещают армирование с учетом соединения ребер и плиты, затем бетонируют конструкцию и проверяют ее геометрию. Направление, размеры и расположение ребер влияют на работу всей плиты, поэтому не выбираются по внешнему виду.'),
('FND_SLAB_USHP',
 'Утепленная шведская плита сочетает несущую бетонную плиту с теплоизоляционным контуром и заранее согласованными проходками. Сначала готовят основание и теплоизоляцию, затем устраивают форму и армирование, проверяют места проходок и бетонируют. Тепловой контур не заменяет проверку несущей способности; оборудование пола и инженерные сети относятся к связанным разделам.'),
('FND_STRIP_MONOLITHIC_RC',
 'Монолитная железобетонная лента проходит под несущими линиями здания и передает их нагрузку на грунт. После подготовки основания устраивают опалубку, размещают арматуру, проверяют положение и защитный слой, затем укладывают и выдерживают бетон. При необходимости готовую ленту защищают от воды и холода; состав защиты зависит от условий подземной части.'),
('FND_STRIP_PRECAST_FBS_FL',
 'Сборная лента собирается из заводских блоков ФБС, а фундаментные плиты ФЛ могут служить ее нижней частью. Подготавливают и принимают основание, монтируют предусмотренные нижние элементы и блоки, контролируют положение, перевязку и швы, затем выполняют защиту от воды. Блок ФБС как часть стены подвала и как часть несущей ленты решает разные задачи.'),
('FND_SUBSTRUCTURE_INSULATION_XPS',
 'Плиты XPS уменьшают теплопередачу через выбранные участки подземной части. Перед монтажом проверяют состояние поверхности и сопряжение с гидроизоляцией, затем укладывают плиты и защищают их от повреждения при последующих работах. XPS не заменяет водозащиту и не должен нарушать работу выбранной гидроизоляционной системы.'),
('FND_SUBSTRUCTURE_WATERPROOFING_COATING',
 'Мастичная гидроизоляция создает сплошной защитный слой на подготовленной подземной поверхности. Основание очищают и принимают, наносят совместимую систему покрытия, проверяют непрерывность слоя и примыкания, затем защищают покрытие от повреждений. Особое внимание уделяют углам, швам и вводам коммуникаций.'),
('FND_SUBSTRUCTURE_WATERPROOFING_MEMBRANE',
 'Мембранная гидроизоляция защищает подземную конструкцию с помощью полотен и соединенных между собой швов. Сначала готовят и проверяют основание, затем монтируют выбранную мембранную систему, выполняют и принимают швы и примыкания, защищают покрытие перед обратной засыпкой. Варианты крепления и соединения различаются у разных систем; их нельзя смешивать произвольно.'),
('FND_UFF',
 'Утепленный финский фундамент сочетает несущую ленточную часть и отдельное утепленное сопряжение с полом по грунту. Сначала устраивают и принимают основание и несущую ленту, затем формируют теплоизоляционный контур и узлы соединения с полом. Важно проверить непрерывность теплозащиты и разделение функций: лента несет здание, а пол и инженерные системы проектируются как связанные, но отдельные части.');

DO $gate$ BEGIN
 IF (SELECT count(*) FROM a22_descriptions) <> 15 THEN
  RAISE EXCEPTION 'A2.2 requires 15 descriptions';
 END IF;
 IF EXISTS (SELECT 1 FROM a22_descriptions d LEFT JOIN module2_technologies t
            ON t.technology_code=d.code AND t.status='ACTIVE'
            WHERE t.id IS NULL) THEN
  RAISE EXCEPTION 'A2.2 foundation technology is missing';
 END IF;
END $gate$;

UPDATE module2_technologies t SET description=d.description, updated_at=CURRENT_TIMESTAMP
FROM a22_descriptions d WHERE t.technology_code=d.code AND t.status='ACTIVE'
 AND t.description IS DISTINCT FROM d.description;
COMMIT;
